def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate the motif by excluding the background and the divider color.
    divider = grid[0][4]
    motif = None
    for y0 in range(0, h, 5):
        for x0 in range(5, w, 5):
            if y0 + 3 >= h or x0 + 3 >= w:
                continue
            cells = [[grid[y0+dy][x0+dx] for dx in range(4)] for dy in range(4)]
            if any(v not in (0, divider) for row in cells for v in row):
                motif = [[v not in (0, divider) for v in row] for row in cells]
                break
        if motif is not None:
            break
    if motif is None:
        return out
    for band, y0 in enumerate(range(0, h, 5)):
        if y0 + 3 >= h:
            continue
        key = grid[y0+1][1]
        for panel, x0 in enumerate(range(0, w, 5)):
            if x0 + 3 >= w:
                continue
            for dy in range(4):
                for dx in range(4):
                    out[y0+dy][x0+dx] = key if motif[dy][dx] else 0
    return out

